window.kbPageData["views/entry/k-d0b4d85959624802"] = {"key":"entry/k-d0b4d85959624802","state":{"route":"entry/k-d0b4d85959624802"},"node":{"id":"k-d0b4d85959624802","mode":"k","title":"整治形式主义为基层减负","type":"观点与论证","domain":"社会治理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["governance","party"],"主类":["观点与论证"],"出处性质":["机构注释"],"学科":["社会治理"],"来源主题":["发展与治理"],"资料类别":["非时政"]},"directorySummary":"3.整治形式主义为基层减负\n形式主义、官僚主义是顽瘴痼疾，必须下大力气坚决纠治。基层是贯彻落实党中央决策\n部署的“最后一公里”，不能被形式主义、官僚主义束缚手脚。\n各地区各部门要严格执行《若干规定》，统筹为基层减负和赋能，切实把基层从形式主\n义、官僚主义束缚中解脱出来，引导广大党员、干部积极担当作为…","sources":[{"id":"362d729a358e2954","label":"整治形式主义为基层减负","topic":"发展与治理","category":"非时政","text":"3.整治形式主义为基层减负\n形式主义、官僚主义是顽瘴痼疾，必须下大力气坚决纠治。基层是贯彻落实党中央决策\n部署的“最后一公里”，不能被形式主义、官僚主义束缚手脚。\n各地区各部门要严格执行《若干规定》，统筹为基层减负和赋能，切实把基层从形式主\n义、官僚主义束缚中解脱出来，引导广大党员、干部积极担当作为，有更多精力抓落实。中\n央层面整治形式主义为基层减负专项工作机制要定期督促检查，中央和国家机关各部门、各\n省级党委和政府在安排部署工作时要实事求是，党委（党组）要履行好主体责任，各级纪检\n监察机关要强化监督执行，确保《若干规定》落到实处。\n——《整治形式主义为基层减负若干规定》","source":{"doc":"6cbfb01fe723bba64b75","first":52,"last":52,"page":52,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"},{"slug":"governance","title":"基层治理与群众参与"}],"units":{"k-d0b4d85959624802":[]}};
